mapper.select:
SELECT FLOOR(UNIX_TIMESTAMP(req_time) / #{bucketSec}) * #{bucketSec} AS b, COUNT(*) AS c
FROM tb_gw_trace_log
WHERE deleted = 0
  AND req_time >= #{since}
AND app_id = #{appId}
AND service_id = #{serviceId}
GROUP BY b

mapper.update:
UPDATE tb_gw_service
SET status = '离线', update_time = #{now}
WHERE deleted = 0 AND service_id = #{serviceId}

UPDATE tb_gw_service
SET status = #{status}, update_time = #{now}
WHERE deleted = 0 AND status != #{status}
  AND (last_heartbeat_time IS NULL OR last_heartbeat_time < #{deadline})
